import{_ as a,o as i,c as e,ag as n}from"./chunks/framework.DXGyWiRo.js";const k=JSON.parse('{"title":"本地 Vite 和测试 Nginx，请求到底怎么走","description":"讲清楚本地 Vite 开发环境和测试环境 Nginx 的请求链路，区分代理、跨域和静态资源来源，帮助前端更准确地定位接口问题。","frontmatter":{"title":"本地 Vite 和测试 Nginx，请求到底怎么走","date":"2026-09-15T00:00:00.000Z","tags":["vite","nginx","前端工程化","接口代理","调试排查"],"category":"工程化","description":"讲清楚本地 Vite 开发环境和测试环境 Nginx 的请求链路，区分代理、跨域和静态资源来源，帮助前端更准确地定位接口问题。"},"headers":[],"relativePath":"frontend/engineering/process-of-api-request.md","filePath":"frontend/engineering/process-of-api-request.md"}'),t={name:"frontend/engineering/process-of-api-request.md"};function p(l,s,h,d,o,c){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="本地-vite-和测试-nginx-请求到底怎么走" tabindex="-1">本地 Vite 和测试 Nginx，请求到底怎么走 <a class="header-anchor" href="#本地-vite-和测试-nginx-请求到底怎么走" aria-label="Permalink to &quot;本地 Vite 和测试 Nginx，请求到底怎么走&quot;">​</a></h1><p>本地能调通，一上测试就 404、跨域，或打到了另一套后端。很多时候不是接口写错了，而是没分清：<strong>开发环境是 Vite 在接请求，测试环境是 Nginx 在接请求</strong>。</p><p>下文域名均为示例：</p><ul><li>测试站点：<code>http://app.test.example.com</code></li><li>CDN：<code>https://cdn.example.com</code></li><li>内网后端：<code>http://10.0.0.10:8101</code></li></ul><hr><h2 id="先看结论" tabindex="-1">先看结论 <a class="header-anchor" href="#先看结论" aria-label="Permalink to &quot;先看结论&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>测试环境</th><th>开发环境</th></tr></thead><tbody><tr><td>入口</td><td>Nginx（<code>app.test.example.com</code>）</td><td>本地 Vite 开发服务器</td></tr><tr><td>页面 / 打包后的 JS、CSS</td><td>Nginx 返回 dist</td><td>Vite 本地编译返回</td></tr><tr><td>接口</td><td><code>/api</code> → Nginx 转发到后端</td><td><code>/dev</code> → Vite proxy 转发</td></tr><tr><td>CDN 资源</td><td>浏览器直连 <code>cdn.example.com</code></td><td>同样直连 CDN</td></tr></tbody></table><p>开发环境的接口会不会经过 Nginx，取决于代理目标配的是测试域名，还是内网机器。</p><hr><h2 id="为什么开发要走-vite-代理" tabindex="-1">为什么开发要走 Vite 代理 <a class="header-anchor" href="#为什么开发要走-vite-代理" aria-label="Permalink to &quot;为什么开发要走 Vite 代理&quot;">​</a></h2><p>浏览器有同源策略。页面在 <code>http://localhost:9000</code>，接口若直接请求 <code>http://app.test.example.com/api</code>，就会跨域。</p><p>Vite 代理的做法是：浏览器只请求同源的 <code>/dev</code>，由开发服务器在 Node 侧转发到真实后端。浏览器看到的始终是同源，跨域问题被代理消掉。</p><p>所以 <code>/dev</code> 不是后端真实路径，只是本地给代理用的前缀。</p><hr><h2 id="测试环境-先到-nginx" tabindex="-1">测试环境：先到 Nginx <a class="header-anchor" href="#测试环境-先到-nginx" aria-label="Permalink to &quot;测试环境：先到 Nginx&quot;">​</a></h2><p>浏览器访问的是已经 build 好的前端，第一站是 Nginx。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器</span></span>
<span class="line"><span>  ├─ HTML / JS / CSS 等站点静态资源 → Nginx 直接返回 dist</span></span>
<span class="line"><span>  ├─ 部分图片 / 字体等           → https://cdn.example.com</span></span>
<span class="line"><span>  └─ /api/... 接口              → Nginx 反代到后端</span></span>
<span class="line"><span>                                 （常见路径：Gateway → 各微服务）</span></span></code></pre></div><p>接口走同源 <code>/api</code>，实际请求形如 <code>http://app.test.example.com/api/user</code>。</p><p>对应的 Nginx 可以简化成：</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    listen </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">80</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    server_name </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app.test.example.com;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 站点静态资源</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    location</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> / </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        root </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/var/www/dist;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        try_files </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$uri $uri/ /index.html;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 接口转给后端</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    location</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> /api/ </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_pass </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://gateway:8080/;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>要点：</p><ul><li>站点静态资源一般由 Nginx 返回，接口由 Nginx 转走。</li><li>不是所有静态资源都来自 Nginx。CDN 上的资源，浏览器会直接请求 <code>cdn.example.com</code>。</li><li>Nginx 后面通常还有 Gateway，不是 Nginx 直接打到某一台业务机。Nginx 负责域名、静态文件和 <code>/api</code> 分流；Gateway 再按服务名做鉴权、路由。</li></ul><hr><h2 id="开发环境-先到-vite" tabindex="-1">开发环境：先到 Vite <a class="header-anchor" href="#开发环境-先到-vite" aria-label="Permalink to &quot;开发环境：先到 Vite&quot;">​</a></h2><p>本地用 Vite 起前端：</p><ul><li>页面入口：<code>http://localhost:9000</code></li><li>接口前缀：<code>/dev</code></li><li>代理目标：<code>http://app.test.example.com/api</code>（也可以改成内网后端）</li></ul><p>代理指向测试环境时，链路是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器 → Vite 开发服务器（http://localhost:9000）</span></span>
<span class="line"><span>  ├─ 源码、HMR、本地静态 → Vite 自己处理（不经过 Nginx）</span></span>
<span class="line"><span>  └─ /dev/...          → Vite proxy</span></span>
<span class="line"><span>                          → http://app.test.example.com/api/...</span></span>
<span class="line"><span>                          → 测试环境 Nginx</span></span>
<span class="line"><span>                          → Gateway / 后端</span></span></code></pre></div><p>Vite 本身是开发服务器，proxy 只是其中一块：只有匹配到的前缀才会转发，页面、HMR、源码模块都在本地编译返回。</p><p>对应配置可以写成：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// vite.config.ts</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> default</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  server: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    port: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    proxy: {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &#39;/dev&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        target: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;http://app.test.example.com/api&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        changeOrigin: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>浏览器请求 <code>http://localhost:9000/dev/user</code>，Vite 转发到 <code>http://app.test.example.com/api/user</code>。</p><hr><h2 id="两个容易混的点" tabindex="-1">两个容易混的点 <a class="header-anchor" href="#两个容易混的点" aria-label="Permalink to &quot;两个容易混的点&quot;">​</a></h2><h3 id="_1-开发环境不一定经过-nginx" tabindex="-1">1. 开发环境不一定经过 Nginx <a class="header-anchor" href="#_1-开发环境不一定经过-nginx" aria-label="Permalink to &quot;1. 开发环境不一定经过 Nginx&quot;">​</a></h3><p>代理目标是可切换的。例如改成直连内网后端：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;http://10.0.0.10:8101&#39;</span></span></code></pre></div><p>这时链路变成：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vite proxy → http://10.0.0.10:8101</span></span></code></pre></div><p>中间没有测试环境的 Nginx。本地能调通，只说明打到了当前 <code>target</code>，不代表测试环境的 Nginx 规则也一定正确。</p><p>只有 <code>target</code> 指向 <code>http://app.test.example.com/api</code> 时，才是「Vite → Nginx → 后端」，本地接口和测试环境走同一套入口。</p><h3 id="_2-静态资源来源不只有一层" tabindex="-1">2. 静态资源来源不只有一层 <a class="header-anchor" href="#_2-静态资源来源不只有一层" aria-label="Permalink to &quot;2. 静态资源来源不只有一层&quot;">​</a></h3><ul><li>测试：页面和打包产物走 Nginx；部分图片、字体走 <code>cdn.example.com</code>。</li><li>开发：页面和模块走 Vite；CDN 资源仍然直连 <code>cdn.example.com</code>。</li></ul><p>排查「资源 404」时，先看请求域名：是本地、测试站点，还是 CDN。</p><h2 id="记住这三句" tabindex="-1">记住这三句 <a class="header-anchor" href="#记住这三句" aria-label="Permalink to &quot;记住这三句&quot;">​</a></h2><ol><li>测试环境：先 Nginx。页面看 dist，接口看 <code>/api</code>。</li><li>开发环境：静态看 Vite，接口看 proxy。</li><li>代理目标决定过不过 Nginx：指向测试域名会经过；指向内网后端会跳过。</li></ol>`,46)])])}const g=a(t,[["render",p]]);export{k as __pageData,g as default};
